128	pub(crate) fn enum_to_string<T: Serialize>(value: &T) -> String {
129	    match serde_json::to_value(value) {
130	        Ok(Value::String(s)) => s,
131	        Ok(other) => other.to_string(),
132	        Err(_) => String::new(),
133	    }
134	}
